import {Component, OnInit} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {AuthService} from "../../services/auth.service";
import {NotifierService} from "../../../../../../services/notifier/notifier.service";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {EventKey} from "../../../../../../services/eventbus/event.key";
import {Router} from "@angular/router";
import {BaseComponent} from "../../../../../../base/components/base.component";
import {SubscriptionContainerService} from "../../../../../../base/services/subscription-container.service";

@Component({
  selector: 'app-login',
  templateUrl: './change-password.component.html',
  styleUrls: ['./change-password.component.scss']
})
export class ChangePasswordComponent extends BaseComponent implements OnInit {

  changePasswordForm = new FormGroup({
    current_password: new FormControl('', Validators.required),
    new_password: new FormControl('', [Validators.required, Validators.minLength(6)]),
    confirm_new_password: new FormControl('', [Validators.required, Validators.minLength(6)]),
  });

  constructor(private authService: AuthService,
              private notifier: NotifierService,
              eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService) {
    super(eventBus, router, subContainer)
  }

  protected componentName(): string {
    return ChangePasswordComponent.name;
  }

  ngOnInit(): void {
    this.changePasswordForm.controls.confirm_new_password.valueChanges.subscribe(value => {

    })

    if (!this.authService.isAuthenticated()) {
      this.navigateByUrl("/login", r => {
        this.notifier.warning("You're not logged in", "Please login first to change your password.")
      })
    }
  }

  isPasswordMatched() {
    return this.changePasswordForm.controls.new_password.value === this.changePasswordForm.controls.confirm_new_password.value
  }


  changePassword(): void {
    let key = this.componentKey(EventKey.AUTH.CHANGE_PASSWORD)
    if (!this.isPasswordMatched()) {
      this.notifier.warning("Password doesn't match", "Confirm password should be same as new password")
      return
    }
    this.authService.changePassword(
      key,
      this.changePasswordForm.value.current_password!!,
      this.changePasswordForm.value.new_password!!
    );
    this.subscribe(key, null, value => {
      this.navigate("/", route => {
        this.notifier.success("Success!", 'Successfully changed password.');
      })
    })
    this.subscribe(this.getMultiErrorKey(key, 1), '/auth/login', value => {
      this.notifier.error(
        "Something went wrong!",
        "Something went wrong! Please try again or contact info@cognitox.org if problem persists."
      );
    });
    this.subscribe(this.getMultiErrorKey(key, 2), '/auth/login', value => {
      this.notifier.warning("Login Failed!", 'Wrong credentials or missing access rights to application.');
    });
  }

  isAuthenticated(): boolean {
    return this.authService.isAuthenticated();
  }

  forgotPassword() {
    this.notifier.info("Later!", "Will be implemented later!")
  }

  register() {
    this.notifier.info("Later!", "Will be implemented later!")
  }


}
