import {Component, Inject, LOCALE_ID} from '@angular/core';
import {Locales, MenuTypeKey, MenuTypes} from "../../../../models/global.config";
import {LocalStorageService} from "../../../../services/storage/localstorage.service";
import {MENU} from "../left-nav/menu.model";

@Component({
  selector: 'app-dash-layout',
  templateUrl: './dash-layout.component.html',
  styleUrls: ['./dash-layout.component.scss']
})
export class DashLayoutComponent {

  protected readonly Locales = Locales;
  menuType = MenuTypes.VERTICAL

  constructor(
    @Inject(LOCALE_ID) protected locale: string
  ) {
    LocalStorageService.retrieveAsync(MenuTypeKey.DASHBOARD, (mt) => {
      this.menuType = (mt as MenuTypes) || MenuTypes.VERTICAL
    })
  }

  protected readonly MENU = MENU;
}
