import {Injectable} from '@angular/core';
import {BaseService} from "../../../../../../base/services/base.service";
import {AuthService} from "../../../../../common/modules/auth/services/auth.service";
import {NotifierService} from "../../../../../../services/notifier/notifier.service";
import {HttpClient, HttpErrorResponse} from "@angular/common/http";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {IParams} from "../../../../../../base/endpoints/iparams";
import {DashEndpoint} from "../../../../dash.endpoint";
import {IPage, ResponseData} from "../../../../../../base/models/IPage";
import {IAuth} from "../../../../../common/modules/auth/models/auth.model";
import {IBlog, IBlogDetail, IBlogReq} from "../models/blog.model";


@Injectable({
  providedIn: 'root'
})
export class BlogService extends BaseService {

  constructor(
    authService: AuthService,
    notifier: NotifierService,
    private http: HttpClient,
    private eventBusService: EventBusService
  ) {
    super(authService, notifier)
  }

  search(key: string, endpoint: string, params: IParams) {
    let url = DashEndpoint.BLOGS.SEARCH(endpoint, params)
    this.http.get<ResponseData<IPage<IBlog>>>(url)
      .subscribe((data: ResponseData<IPage<IBlog>>) => {
        this.eventBusService.publish(key, data.body)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.search(key, endpoint, params)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchSingle(key: string, endpoint: string, id: number) {
    this.http.get<ResponseData<IBlogDetail>>(DashEndpoint.BLOGS.GET(endpoint, id))
      .subscribe((data: ResponseData<IBlogDetail>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchSingle(key, endpoint, id)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchBySlug(key: string, slug: string) {
    this.http.get<ResponseData<IBlogDetail>>(DashEndpoint.BLOGS.GET_BY_SLUG_PUBLIC(slug))
      .subscribe((data: ResponseData<IBlogDetail>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchBySlug(key, slug)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  upsert(key: string, endpoint: string, blogReq: IBlogReq, exId: number | null) {
    let url = exId == null ? DashEndpoint.BLOGS.CREATE(endpoint)
      : DashEndpoint.BLOGS.UPDATE(endpoint, exId)

    let observable = exId == null ?
      this.http.post<ResponseData<IBlogDetail>>(url, blogReq)
      : this.http.patch<ResponseData<IBlogDetail>>(url, blogReq)

    observable.subscribe(res => {
      this.eventBusService.publish(key, res.body)
    }, (err: HttpErrorResponse) => {
      this.handleError(err, (auth: IAuth) => {
        this.upsert(key, endpoint, blogReq, exId)
      }, (err: HttpErrorResponse) => {
        this.eventBusService.publish(this.getErrorKey(key), err)
      })
    })
  }

  publish(key: string, endpoint: string, blogId: number, publish: boolean) {
    let url = DashEndpoint.BLOGS.PUBLISH(endpoint, blogId, {published: publish})

    this.http.patch<ResponseData<IBlogDetail>>(url, null)
      .subscribe(res => {
        this.eventBusService.publish(key, res.body)
      }, (err: HttpErrorResponse) => {
        this.handleError(err, (auth: IAuth) => {
          this.publish(key, endpoint, blogId, publish)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

}
